  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']

    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)

    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of feasible range')

    names = [s['name'] for s in segments]
    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - total_min
    capacities = {s['name']: s['capacity'] for s in segments}
    importances = {s['name']: s['importance'] for s in segments}

    while remaining > 0:
        best_idx = None
        best_ratio = -1.0
        for i, s in enumerate(segments):
            name = s['name']
            current = alloc[name]
            if current >= capacities[name]:
                continue
            next_pos = current + 1
            ratio = importances[name] / next_pos
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx is None:
            break
        best_name = segments[best_idx]['name']
        alloc[best_name] += 1
        remaining -= 1

    total_allocated = sum(alloc.values())
    return {
        'allocations': alloc,
        'total_allocated': total_allocated
    }
